// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C(address(this), address(this), address(this));
    }

    function testFuzz_property(
        address baseToken,
        address nft,
        uint128 virtualBaseTokenReserves,
        uint128 virtualNftReserves,
        uint56 changeFee,
        uint16 feeRate,
        bytes32 merkleRoot,
        bool useStolenNftOracle,
        bool payRoyalties
    ) public {
        // Admissible domain: initialize must succeed, so feeRate must be <= 5000,
        // and baseToken and nft must be distinguishable addresses.
        feeRate = uint16(bound(feeRate, 0, 5_000));
        vm.assume(baseToken != address(0));
        vm.assume(nft != address(0));
        vm.assume(baseToken != nft);

        c.initialize(
            baseToken,
            nft,
            virtualBaseTokenReserves,
            virtualNftReserves,
            changeFee,
            feeRate,
            merkleRoot,
            useStolenNftOracle,
            payRoyalties
        );

        // General rule: after a successful initialize, the pool's baseToken
        // is exactly the _baseToken argument supplied by the caller.
        assertTrue(c.baseToken() == baseToken);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C(address(this), address(this), address(this));
    }

    function testFuzz_property(
        address baseToken0,
        address nft0,
        uint128 vBase,
        uint128 vNft,
        uint56 changeFee,
        uint16 feeRate,
        bytes32 merkleRoot,
        bool useOracle,
        bool payRoyalties
    ) public {
        // nft must be nonzero for the rule to be expressible as baseToken == _baseToken
        vm.assume(baseToken0 != address(0));
        vm.assume(nft0 != address(0));
        vm.assume(baseToken0 != nft0);

        c.initialize(
            baseToken0,
            nft0,
            vBase,
            vNft,
            changeFee,
            feeRate,
            merkleRoot,
            useOracle,
            payRoyalties
        );

        // General rule: after initialize(_baseToken, _nft, ...), the stored base token
        // is exactly the _baseToken parameter (and the stored NFT is _nft).
        assertTrue(c.baseToken() == baseToken0 && c.nft() == nft0);
    }
}
